236	  } catch (e) {
237	    return { ...empty, errors: [{ what: `${name} is not valid JSON: ${e.message}`, fix: 'fix the JSON syntax' }] };
238	  }
239	  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
240	    return { ...empty, errors: [{ what: `${name} must be a JSON object`, fix: 'wrap the settings in an object: { "packs": [ ... ] }' }] };
241	  }
242	
243	  const errors = [];
244	  for (const key of Object.keys(raw)) {
245	    if (!KNOWN_CONFIG_KEYS.includes(key)) {
246	      errors.push({ what: `unknown setting "${key}"`, fix: `remove it or fix the name — valid settings: ${CONFIG_KEYS.join(', ')}` });
247	    }
248	  }
249	
250	  // --- packs: each entry a pack id or { id, config?, rules?, accept?, via? } ---
